        margin-top: 1.5rem;
      }

      .form-field {
        margin-bottom: 1.25rem;
      }

      label {
        display: inline-block;
        margin-bottom: 0.5rem;
        font-weight: 700;
      }

      .required-mark {
        color: var(--error);
      }

      input {
        width: 100%;
        padding: 0.95rem 1rem;
        border: 1px solid var(--border);
        border-radius: 0.95rem;
        background: #fff;
        color: var(--text);
        font: inherit;
        transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
      }

      input::placeholder {
        color: #7987a1;
      }

      input:hover {
        border-color: #9daecc;
      }

      input:focus {
        outline: 2px solid transparent;
        outline-offset: 2px;
        border-color: var(--primary);
        box-shadow: 0 0 0 4px rgba(49, 94, 251, 0.16);
      }

      input[aria-invalid="true"] {
        border-color: var(--error);
        background: var(--error-bg);
      }

      .field-help,
      .field-error,
      .form-status {
        margin-top: 0.5rem;
        font-size: 0.95rem;
        line-height: 1.45;
      }

      .field-help {
        color: var(--muted);
      }

      .field-error {
        color: var(--error);
        font-weight: 600;
      }

      .form-status {
        min-height: 1.45rem;
        color: #126436;
        font-weight: 600;
      }

      .submit-button {
        width: 100%;
        margin-top: 0.5rem;
        border: 0;
        border-radius: 999px;
        padding: 1rem 1.25rem;
        background: linear-gradient(135deg, var(--primary), #5c82ff);
        color: #fff;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
        box-shadow: 0 14px 24px rgba(49, 94, 251, 0.24);
      }

      .submit-button:hover {
        transform: translateY(-1px);
      }

      .submit-button:focus {
        outline: 2px solid transparent;
        outline-offset: 3px;
        box-shadow:
          0 0 0 4px rgba(49, 94, 251, 0.22),
          0 14px 24px rgba(49, 94, 251, 0.24);
      }

      .submit-button:active {
        transform: translateY(0);
      }

      @media (max-width: 860px) {
        .support-layout {
          grid-template-columns: 1fr;
        }

        .support-panel,
        .form-card {
          padding: 1.5rem;
        }
      }

      @media (max-width: 480px) {
        .page-shell {
          padding: 1rem;
