  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        errors: {},
        statusMessage: "",
      };

      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const phonePattern = /^\+?[0-9\s().-]{7,20}$/;

      function HeroPanel() {
        return `
          <section class="support-panel" aria-labelledby="support-heading">
            <div>
              <span class="eyebrow">Support</span>
              <h1 id="support-heading">Talk to our support team with one quick form.</h1>
              <p class="lead">
                Share your contact details and our product specialists will follow up with the right help for your account, setup, or billing questions.
              </p>
            </div>
            <ul class="highlights" aria-label="Support benefits">
              <li>
                <span class="icon" aria-hidden="true">1</span>
                <div>
                  <strong>Fast routing</strong>
                  <span>Your request gets to the right specialist without extra back-and-forth.</span>
                </div>
              </li>
              <li>
                <span class="icon" aria-hidden="true">2</span>
                <div>
                  <strong>Clear follow-up</strong>
                  <span>We use your preferred contact details to keep support updates simple.</span>
                </div>
              </li>
            </ul>
          </section>
        `;
      }

      function ContactForm() {
        const fullNameError = state.errors.fullName || "";
        const emailError = state.errors.email || "";
        const phoneError = state.errors.phone || "";

        return `
          <section class="form-card" aria-labelledby="contact-form-title">
            <h2 id="contact-form-title">Contact support</h2>
            <p>Fields marked with <span class="required-mark">*</span> are required.</p>
            <form id="contact-form" novalidate>
              <div class="form-field">
                <label for="fullName">Full name <span class="required-mark" aria-hidden="true">*</span></label>
                <input
                  id="fullName"
                  name="fullName"
                  type="text"
                  autocomplete="name"
                  placeholder="Jordan Lee"
                  value="${escapeHtml(state.values.fullName)}"
                  required
                  aria-required="true"
                  aria-invalid="${fullNameError ? "true" : "false"}"
                  aria-describedby="fullName-error"
                />
                <div id="fullName-error" class="field-error" aria-live="polite">${escapeHtml(fullNameError)}</div>
              </div>

              <div class="form-field">
                <label for="email">Email address <span class="required-mark" aria-hidden="true">*</span></label>
                <input
                  id="email"
                  name="email"
                  type="email"
                  inputmode="email"
                  autocomplete="email"
                  placeholder="name@company.com"
                  value="${escapeHtml(state.values.email)}"
                  required
                  aria-required="true"
                  aria-invalid="${emailError ? "true" : "false"}"
                  aria-describedby="email-error"
                />
                <div id="email-error" class="field-error" aria-live="polite">${escapeHtml(emailError)}</div>
              </div>

              <div class="form-field">
                <label for="phone">Phone number</label>
                <input
                  id="phone"
                  name="phone"
                  type="tel"
                  inputmode="tel"
                  autocomplete="tel"
                  placeholder="+1 (555) 123-4567"
                  value="${escapeHtml(state.values.phone)}"
                  aria-invalid="${phoneError ? "true" : "false"}"
                  aria-describedby="phone-help phone-error"
                />
                <div id="phone-help" class="field-help">Expected format: +1 (555) 123-4567 or 555-123-4567.</div>
                <div id="phone-error" class="field-error" aria-live="polite">${escapeHtml(phoneError)}</div>
              </div>

              <button class="submit-button" type="submit">Submit request</button>
              <div class="form-status" role="status" aria-live="polite">${escapeHtml(state.statusMessage)}</div>
            </form>
          </section>
        `;
      }

      function App() {
        return `
          <main id="main-content" class="page-shell">
            <div class="support-layout">
              ${HeroPanel()}
              ${ContactForm()}
            </div>
          </main>
        `;
      }

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function validateField(name, value) {
        const trimmedValue = value.trim();

        if (name === "fullName") {
          if (!trimmedValue) {
            return "Enter your full name.";
          }
          return "";
        }

        if (name === "email") {
          if (!trimmedValue) {
            return "Enter your email address.";
          }
          if (!emailPattern.test(trimmedValue)) {
            return "Enter a valid email address, such as name@company.com.";
          }
          return "";
        }

        if (name === "phone") {
          if (!trimmedValue) {
            return "";
          }
          if (!phonePattern.test(trimmedValue)) {
            return "Enter a valid phone number using digits, spaces, parentheses, periods, or hyphens.";
          }
          return "";
        }

        return "";
      }

      function validateForm(values) {
        return {
          fullName: validateField("fullName", values.fullName),
          email: validateField("email", values.email),
          phone: validateField("phone", values.phone),
        };
      }

      function bindFormEvents() {
        const form = document.getElementById("contact-form");
        if (!form) {
          return;
        }

        form.addEventListener("input", (event) => {
          const target = event.target;
          if (!(target instanceof HTMLInputElement)) {
            return;
          }

          state.values[target.name] = target.value;
          state.errors[target.name] = validateField(target.name, target.value);
          state.statusMessage = "";
          render();
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          state.errors = validateForm(state.values);
          const firstInvalidField = ["fullName", "email", "phone"].find((fieldName) => state.errors[fieldName]);

          if (firstInvalidField) {
            state.statusMessage = "";
            render();
            const invalidInput = document.getElementById(firstInvalidField);
            if (invalidInput instanceof HTMLElement) {
              invalidInput.focus();
            }
            return;
          }

          state.statusMessage = "Your support request is ready to send.";
          render();
        });
      }

      function render() {
        const appRoot = document.getElementById("app");
        appRoot.innerHTML = App();
        bindFormEvents();
      }

      render();
    </script>
  </body>
</html>
